<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { ApiError, describeError, request, workspacePath, formatDate, type Workspace } from './api'
import { discoveryProviders, type DiscoverySource, type DiscoveryRule, type DiscoveryRun } from './discovery'
const props=defineProps<{workspace:Workspace}>(); const emit=defineEmits<{sessionExpired:[]}>()
const tab=ref<'sources'|'rules'|'runs'>('sources');const search=ref('');const sourceFilter=ref('');const showToken=ref(false);const selected=computed(()=>sources.value.find(s=>s.source===selectedSource.value)??sources.value[0]);const visibleSources=computed(()=>sources.value.filter(s=>(!sourceFilter.value||s.provider===sourceFilter.value)&&(!search.value.trim()||[s.source,s.database,s.provider,s.scopes.join(',')].some(v=>v.toLowerCase().includes(search.value.trim().toLowerCase())))));const coverageLabels:Record<string,string>={unknown:'未知',not_collected:'未采集',bounded_sample:'有界采样',observed:'已观察',per_table_api:'一跳目录接口',current_account_visible_grants:'当前账号可见授权',declared_validator_and_sample_inference:'声明与采样推断',openmetadata_declared_columns_comments_tags_constraints:'目录字段、标签及约束'};const coverageText=(value:string)=>coverageLabels[value]??value;
async function copyToken(){try{await navigator.clipboard.writeText(token.value);notice.value='令牌已复制，请保存在客户侧受控环境。'}catch{notice.value='复制不可用，请临时显示并保存令牌。'}}
const ruleStatusLabels:Record<string,string>={draft:'草稿',published:'已发布',retired:'已停用'}
const base=workspacePath(props.workspace.slug)+'/discovery';const sources=ref<DiscoverySource[]>([]);const rules=ref<DiscoveryRule[]>([]);const runs=ref<DiscoveryRun[]>([]);const error=ref('');const notice=ref('');const busy=ref(false);const token=ref('');const editing=ref<number|undefined>();const scopeText=ref('');const selectedSource=ref('');const owner=computed(()=>props.workspace.role==='owner');const canEdit=computed(()=>owner.value||props.workspace.role==='operator');let timer:ReturnType<typeof setInterval>|undefined
const blank=()=>({source:'',provider:'mysql',system:'mysql',database:'',scopes:[] as string[],service:'',intervalMinutes:15,enabled:true,revision:0});const form=ref(blank());const rule=ref<DiscoveryRule>({key:'',version:1,name:'',kind:'keyword',target:'metadata',category:'business',expression:'',dictionary:[],status:'draft'});const dictionary=ref('');const ruleForm=ref(false);const sourceForm=ref(false)
const selectedRuleKey=ref('');const selectedRule=computed(()=>rules.value.find(r=>r.key+':'+r.version===selectedRuleKey.value)??rules.value[0]);const displayedRule=computed(()=>ruleForm.value?rule.value:selectedRule.value);const ruleKindLabels:Record<string,string>={keyword:'关键词',regexp:'RE2 正则',dictionary:'精确词典'};function scrollField(id:string){document.getElementById(id)?.scrollIntoView({block:'center',behavior:'smooth'})}
function failed(e:unknown){if(e instanceof ApiError&&e.status===401){emit('sessionExpired');return}error.value=describeError(e)}
async function load(){try{const [a,b]=await Promise.all([request<{items:DiscoverySource[]}>(base+'/sources'),request<{items:DiscoveryRule[]}>(base+'/rules')]);sources.value=a.items;rules.value=b.items}catch(e){failed(e)}}
function edit(s?:DiscoverySource){form.value=s?{source:s.source,provider:s.provider,system:s.system,database:s.database,scopes:[...s.scopes],service:s.service,intervalMinutes:s.intervalMinutes,enabled:s.enabled,revision:s.revision}:blank();editing.value=s?.id;scopeText.value=s?.scopes.join(',')||'';sourceForm.value=true;token.value='';showToken.value=false}
async function save(){busy.value=true;error.value='';try{form.value.scopes=scopeText.value.split(',').map(v=>v.trim()).filter(Boolean);if(form.value.provider!=='openmetadata')form.value.system=form.value.provider;const result=await request<{source:DiscoverySource;token:string}>(base+'/sources'+(editing.value?'/'+editing.value:''),{method:editing.value?'PUT':'POST',body:JSON.stringify(form.value)});showToken.value=false;token.value=result.token;sourceForm.value=false;notice.value='任务已保存。客户侧采集器在线时会领取计划和立即任务。';await load()}catch(e){failed(e)}finally{busy.value=false}}
async function queue(s:DiscoverySource,mode:string){error.value='';try{await request(base+'/sources/'+s.id+'/run',{method:'POST',body:JSON.stringify({revision:s.revision,mode})});notice.value=mode==='test'?'已排队测试连接。请保持客户侧采集器在线，并查看运行记录。':'已排队立即采集。';await load();await history(s)}catch(e){failed(e)}}
async function history(s:DiscoverySource){try{selectedSource.value=s.source;const r=await request<{items:DiscoveryRun[]}>(base+'/sources/'+s.id+'/runs');runs.value=r.items}catch(e){failed(e)}}
async function rotate(s:DiscoverySource){try{const r=await request<{token:string}>(base+'/sources/'+s.id+'/token',{method:'POST',body:JSON.stringify({revision:s.revision})});showToken.value=false;token.value=r.token;notice.value='旧令牌已失效，请更新客户侧采集器。';await load()}catch(e){failed(e)}}
async function saveRule(){busy.value=true;try{rule.value.dictionary=dictionary.value.split('\n').map(v=>v.trim()).filter(Boolean);await request(base+'/rules',{method:'POST',body:JSON.stringify(rule.value)});ruleForm.value=false;notice.value='识别规则版本已保存。发布后由客户侧采集器领取。';await load()}catch(e){failed(e)}finally{busy.value=false}}
async function publish(r:DiscoveryRule){try{await request(base+'/rules/publish',{method:'POST',body:JSON.stringify({key:r.key,version:r.version})});await load()}catch(e){failed(e)}}
function newVersion(r?:DiscoveryRule){rule.value=r?{...r,version:Math.max(...rules.value.filter(v=>v.key===r.key).map(v=>v.version))+1,status:'draft',dictionary:[...r.dictionary]}:{key:'',version:1,name:'',kind:'keyword',target:'metadata',category:'business',expression:'',dictionary:[],status:'draft'};dictionary.value=rule.value.dictionary.join('\n');ruleForm.value=true}
onMounted(()=>{void load();timer=setInterval(async()=>{await load();const s=sources.value.find(v=>v.source===selectedSource.value);if(s)await history(s)},15000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<template>
<section class="discovery-page">
 <header class="page-header"><div><p class="eyebrow">配置接入 / 数据发现</p><h1>多源自动发现</h1><p>采用实际来源、版本和工作区范围，保留每一步操作与证据。</p></div><div class="page-actions"><button v-if="owner" class="button primary" @click="edit()">新增来源</button><button class="button" @click="tab='rules';sourceForm=false">识别规则</button></div></header>
 <p v-if="error" role="alert" class="message message-error">{{error}}</p><p v-if="notice" role="status" class="message message-success">{{notice}}</p>
 <aside v-if="token" class="discovery-card discovery-token"><div><h2>客户侧任务令牌</h2><span class="badge">仅此时显示</span></div><input :type="showToken?'text':'password'" :value="token" readonly aria-label="客户侧任务令牌"><p>令牌仅配置于客户侧 SCARLET_DISCOVERY_TOKEN。数据库连接及 OpenMetadata 凭据继续留在客户环境。</p><div class="actions"><button class="button primary" @click="copyToken">复制令牌</button><button class="button" @click="showToken=!showToken">{{showToken?'隐藏':'临时显示'}}</button><button class="button" @click="token='';showToken=false">我已保存</button></div></aside>
 <div v-if="sourceForm" class="discovery-form-workbench">
  <nav class="panel discovery-steps" aria-label="配置步骤"><h2>配置步骤</h2><button type="button" @click="scrollField('discovery-source-name')">1. 来源与接入方式</button><button type="button" @click="scrollField('discovery-source-scope')">2. 授权范围</button><button type="button" @click="scrollField('discovery-source-frequency')">3. 频率与自动化</button></nav>
  <form class="panel discovery-form" @submit.prevent="save"><div class="panel-heading"><h2>{{editing?'编辑':'新增'}}发现来源</h2><span v-if="editing" class="badge">修订 v{{form.revision}}</span></div><div class="discovery-fields"><label id="discovery-source-name">来源名称<input v-model="form.source" required maxlength="80"></label><label>接入方式<select v-model="form.provider" :disabled="Boolean(editing)"><option v-for="(label,key) in discoveryProviders" :key="key" :value="key">{{label}}</option></select></label><label>数据库名称<input v-model="form.database" required maxlength="128"></label><label id="discovery-source-scope">授权范围（逗号分隔）<input v-model="scopeText" placeholder="PG/OM: schema；Mongo: collection；MySQL留空"></label><template v-if="form.provider==='openmetadata'"><label>OpenMetadata 服务名<input v-model="form.service" required></label><label>源数据库类型<select v-model="form.system"><option v-for="s in ['postgresql','mysql','mariadb','mongodb','mssql','oracle','db2','hive','clickhouse','snowflake','bigquery','redshift','trino','presto','spark','databricks']" :key="s">{{s}}</option></select></label></template><label id="discovery-source-frequency">周期（分钟）<input v-model.number="form.intervalMinutes" type="number" min="1" max="1440" required></label><label class="discovery-check"><input v-model="form.enabled" type="checkbox">启用定期任务</label></div><div class="discovery-form-footer"><button class="button" type="button" :disabled="busy" @click="sourceForm=false">取消</button><button class="button primary" :disabled="busy">{{busy?'正在保存…':'保存配置'}}</button></div></form>
  <aside class="section-stack"><section class="panel"><div class="panel-heading"><h2>采用范围</h2></div><dl class="discovery-defs"><div><dt>工作区</dt><dd>{{workspace.name}}</dd></div><div><dt>来源</dt><dd>{{form.source||'待填写'}}</dd></div><div><dt>实际数据库</dt><dd>{{form.database||'待填写'}}</dd></div><div><dt>凭据</dt><dd>仅客户侧环境保存</dd></div></dl></section><section class="panel"><div class="panel-heading"><h2>核验提示</h2></div><p class="discovery-callout">配置修订会使旧批次失效。连接诊断与目录采集分别记录，下一次成功采集后才恢复当前目录关联。</p></section></aside>
 </div>
 <div v-else class="discovery-workbench">
  <section class="panel discovery-main"><div class="panel-heading"><h2>{{tab==='rules'?'识别规则':tab==='runs'?'采集运行记录':'来源任务'}}</h2><span class="badge">{{tab==='rules'?rules.length:sources.length}} 项配置</span></div><div class="discovery-tabs" role="tablist" aria-label="数据发现内容"><button :class="{active:tab==='sources'}" role="tab" :aria-selected="tab==='sources'" @click="tab='sources'">来源任务</button><button :class="{active:tab==='rules'}" role="tab" :aria-selected="tab==='rules'" @click="tab='rules'">识别规则</button><button :class="{active:tab==='runs'}" role="tab" :aria-selected="tab==='runs'" @click="tab='runs'">运行记录</button></div>
  <template v-if="tab==='sources'"><div class="filter-bar"><label>接入方式<select v-model="sourceFilter"><option value="">全部来源</option><option v-for="(label,key) in discoveryProviders" :key="key" :value="key">{{label}}</option></select></label><label class="discovery-search">检索<input v-model="search" type="search" placeholder="来源、数据库或范围"></label></div><div class="table-scroll"><table class="data-table"><thead><tr><th>来源 / 数据库</th><th>提供方与范围</th><th>最新采集</th><th>频率与计划</th><th>操作</th></tr></thead><tbody><tr v-for="s in visibleSources" :key="s.id" :class="{selected:selected?.id===s.id}"><th scope="row"><button class="source-select" @click="history(s)">{{s.source}}</button><small>{{s.database}} · v{{s.revision}}</small></th><td>{{discoveryProviders[s.provider]}}<small>{{s.system}} · {{s.scopes.join(', ')||'数据库内授权目录'}}</small></td><td><span class="badge" :class="s.latestRun?.status==='error'?'status-needs_work':s.latestRun?.status==='success'?'status-verified':''">{{!s.enabled?'已暂停':s.running?'采集中':s.queued?'等待客户采集器':s.latestRun?.status==='success'?'已采集':s.latestRun?.status==='error'?'采集失败':'尚未采集'}}</span><small v-if="s.latestRun">{{formatDate(s.latestRun.observedAt)}}</small></td><td>每 {{s.intervalMinutes}} 分钟<small>{{formatDate(s.nextRunAt)}}</small></td><td><div class="source-actions"><button class="button" @click="history(s);tab='runs'">运行记录</button><template v-if="owner"><button class="button" @click="edit(s)">配置</button><button class="button" :disabled="s.running||!s.enabled" @click="queue(s,'test')">测试连接</button><button class="button" :disabled="s.running||!s.enabled" @click="queue(s,'collect')">立即采集</button><button class="button" @click="rotate(s)">更换令牌</button></template></div></td></tr><tr v-if="!visibleSources.length"><td colspan="5" class="empty-state">{{search||sourceFilter?'没有符合筛选条件的来源。':'尚无多源采集任务。现有 PostgreSQL 托管任务继续在自动采集中配置。'}}</td></tr></tbody></table></div></template>
  <template v-else-if="tab==='runs'"><div class="filter-bar"><label>来源<select :value="selectedSource" @change="history(sources.find(s=>s.source===($event.target as HTMLSelectElement).value)!)"><option value="" disabled>选择来源</option><option v-for="s in sources" :key="s.id" :value="s.source">{{s.source}}</option></select></label><span>最近30次运行 · 观察时间与入库批次分别保留</span></div><p v-if="!runs.length" class="empty-state">选择来源后查看最近运行，排队任务需要客户侧采集器在线。</p><article v-for="r in runs" :key="r.id" class="discovery-run"><div><strong>{{r.mode==='test'?'连接诊断':'目录采集'}} #{{r.id}}</strong><span class="badge" :class="r.status==='success'?'status-verified':'status-needs_work'">{{r.status==='success'?'成功':'失败'}}</span></div><p>{{formatDate(r.observedAt)}} · 配置 v{{r.revision}}</p><p v-if="r.status==='error'" class="message message-error">采集失败，请在客户侧检查连接、TLS、账号权限与范围。</p><dl v-else class="run-coverage"><div v-for="key in (['metadata','content','permissions','lineage'] as const)" :key="key"><dt>{{ {metadata:'元数据',content:'内容',permissions:'权限',lineage:'血缘'}[key] }}</dt><dd>{{coverageText(r.coverage[key])}}</dd></div></dl><details><summary>范围与限制</summary><pre>{{JSON.stringify(r.coverage,null,2)}}</pre></details></article></template>
  <template v-else><div class="filter-bar"><span>命中为候选，人工确认优先；发布版本固定到采集批次。</span><button v-if="canEdit" class="button" @click="newVersion()">新增规则</button></div><div class="discovery-rule-layout"><nav class="discovery-rule-list" aria-label="识别规则版本"><article v-for="r in rules" :key="r.key+':'+r.version" :class="{active:selectedRule?.key===r.key && selectedRule?.version===r.version}"><button class="rule-select" @click="selectedRuleKey=r.key+':'+r.version;ruleForm=false"><strong>{{r.name}}</strong><small>{{r.key}}</small><span>v{{r.version}} · {{r.status?ruleStatusLabels[r.status]||'状态待确认':'内置'}}</span></button><div v-if="canEdit&&!r.key.startsWith('builtin.')" class="actions"><button class="button" @click="newVersion(r)">新版本</button><button v-if="r.status==='draft'" class="button" @click="publish(r)">发布</button></div></article><p v-if="!rules.length" class="empty-state">尚无识别规则。</p></nav><div class="discovery-rule-main"><form v-if="ruleForm" class="discovery-rule-editor" @submit.prevent="saveRule"><h3>识别规则新版本</h3><div class="discovery-fields"><label>规则标识<input v-model="rule.key" required maxlength="80"></label><label>规则名称<input v-model="rule.name" required maxlength="160"></label><label>版本<input v-model.number="rule.version" type="number" min="1" required></label><label>类型<select v-model="rule.kind"><option value="keyword">关键词（逗号分隔）</option><option value="regexp">RE2正则</option><option value="dictionary">精确词典</option></select></label><label>识别范围<select v-model="rule.target"><option value="metadata">字段名 / 注释 / 类型</option><option value="content">客户侧受限内容样本</option></select></label><label>候选类别<input v-model="rule.category" required maxlength="80"></label><label v-if="rule.kind!=='dictionary'" class="field-wide">表达式<textarea v-model="rule.expression" required maxlength="2048"></textarea></label><label v-else class="field-wide">词典（每行一项，最多1000项）<textarea v-model="dictionary" required></textarea></label><label>保存状态<select v-model="rule.status"><option value="draft">草稿</option><option value="published">发布</option></select></label></div><div class="actions"><button class="button primary" :disabled="busy">保存版本</button><button type="button" class="button" @click="ruleForm=false">取消</button></div></form><section v-if="!ruleForm && selectedRule" class="discovery-rule-read"><p class="eyebrow">已采用规则版本</p><h3>{{selectedRule.name}}</h3><span class="badge">v{{selectedRule.version}} · {{selectedRule.status?ruleStatusLabels[selectedRule.status]:'内置'}}</span><dl><div><dt>规则类型</dt><dd>{{ruleKindLabels[selectedRule.kind]}}</dd></div><div><dt>识别范围</dt><dd>{{selectedRule.target==='metadata'?'字段名、注释与类型':'客户侧受限内容样本'}}</dd></div><div><dt>候选类别</dt><dd>{{selectedRule.category}}</dd></div><div><dt>{{selectedRule.kind==='dictionary'?'词典项数':'表达式'}}</dt><dd>{{selectedRule.kind==='dictionary'?selectedRule.dictionary.length+' 项':selectedRule.expression}}</dd></div></dl><p>已发布版本保留原内容。后续采集批次记录实际采用的版本、命中数与已观察数。</p></section></div></div></template>
  </section>
  <aside class="context-rail section-stack"><section v-if="tab==='rules'" class="panel"><div class="panel-heading"><h2>规则采用依据</h2></div><dl class="discovery-defs"><template v-if="displayedRule"><div><dt>当前规则</dt><dd>{{displayedRule.name||'待填写'}}</dd></div><div><dt>版本</dt><dd>v{{displayedRule.version}}</dd></div><div><dt>识别方法</dt><dd>{{ruleKindLabels[displayedRule.kind]}}</dd></div><div><dt>识别范围</dt><dd>{{displayedRule.target==='metadata'?'元数据':'客户侧受限内容'}}</dd></div><div><dt>候选类别</dt><dd>{{displayedRule.category}}</dd></div></template></dl><p class="discovery-callout">规则命中形成候选线索。分类确认、采用标准和来源覆盖共同决定能否进入检查复核。</p></section><section v-else class="panel"><div class="panel-heading"><h2>当前范围与缺口</h2></div><dl class="discovery-defs"><div><dt>来源</dt><dd>{{selected?.source||'尚未选择'}}</dd></div><div><dt>实际类型</dt><dd>{{selected?.system||'未知'}}</dd></div><div><dt>授权范围</dt><dd>{{selected?.scopes.join(', ')||'按来源配置'}}</dd></div><template v-if="selected?.latestRun?.coverage"><div v-for="key in (['metadata','content','permissions','lineage'] as const)" :key="key"><dt>{{ {metadata:'元数据',content:'内容',permissions:'来源权限',lineage:'血缘'}[key] }}</dt><dd>{{coverageText(selected.latestRun.coverage[key])}}</dd></div></template><div v-else><dt>覆盖结果</dt><dd>尚未取得</dd></div></dl><div class="discovery-rail-actions"><button v-if="selected" class="button primary" @click="history(selected);tab='runs'">查看运行依据</button></div></section><section class="panel"><div class="panel-heading"><h2>取证路径</h2></div><ol class="discovery-spine"><li>授权来源与范围</li><li>字段与候选规则</li><li>采用标准与G02证据</li></ol><p class="discovery-callout">未知权限不视为无授权。OpenMetadata 标签和所有者不能替代源数据库ACL证据。</p></section></aside>
 </div>
</section>
</template>
<style scoped>
.discovery-page{display:grid;gap:16px}.discovery-workbench{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:16px;align-items:start}.discovery-main{min-width:0}.discovery-tabs{display:flex;border-bottom:1px solid var(--line);padding:0 14px;gap:3px}.discovery-tabs button{background:none;border:0;border-bottom:2px solid transparent;color:var(--secondary);padding:13px 15px;font-size:12px}.discovery-tabs button.active{color:var(--accent);border-bottom-color:var(--accent);font-weight:700}.discovery-form-workbench{display:grid;grid-template-columns:190px minmax(0,1fr) 280px;gap:16px;align-items:start}.discovery-steps{padding:18px;display:grid;gap:20px;font-size:12px}.discovery-steps h2{font-size:16px}.discovery-form{padding:0}.discovery-fields{padding:20px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.discovery-fields label{display:grid;gap:7px;font-size:12px;font-weight:600;min-width:0}.discovery-fields .field-wide{grid-column:1/-1}.discovery-fields input,.discovery-fields select,.discovery-fields textarea,.filter-bar input,.filter-bar select{font:inherit;padding:9px 10px;border:1px solid var(--input-line);border-radius:6px;max-width:100%;min-width:0;background:white;color:var(--ink)}.discovery-fields textarea{min-height:100px}.discovery-fields .discovery-check{display:flex;align-items:center;gap:8px;align-self:center}.discovery-fields input[type=checkbox]{width:auto}.discovery-form-footer{display:flex;justify-content:flex-end;gap:8px;padding:15px 20px;background:#fbfdff;border-top:1px solid var(--line)}.discovery-search{margin-left:auto}.filter-bar label{display:flex;align-items:center;gap:8px}.discovery-workbench table{min-width:0!important;width:100%;border-collapse:collapse}.discovery-workbench th,.discovery-workbench td{font-size:12px;padding:13px 14px!important;border-bottom:1px solid var(--line);vertical-align:top}.discovery-workbench th small,.discovery-workbench td small{display:block;font-size:10px;color:var(--secondary);margin-t